import itertools

def is_golomb(marks):
    diffs = set()
    n = len(marks)
    for i in range(n):
        for j in range(i + 1, n):
            diff = marks[j] - marks[i]
            if diff in diffs:
                return False
            diffs.add(diff)
    return True

def find_golomb_ruler(n, max_len):
    for marks in itertools.combinations(range(1, max_len + 1), n - 1):
        ruler = (0,) + marks
        if is_golomb(ruler):
            return ruler
    return None

print(find_golomb_ruler(5, 20))
